import products from './products.json' with { type: 'json' };

const TOOL_DEFINITIONS = {
  inventory_search: {
    name: 'inventory_search',
    description: 'Search products by name (case-insensitive substring match).',
    inputSchema: {
      type: 'object',
      properties: {
        query: {
          type: 'string',
          description: 'Search substring matched against product names (case-insensitive).',
        },
        limit: {
          type: 'integer',
          minimum: 1,
          maximum: 10,
          description: 'Maximum number of results to return (1-10). Defaults to 10.',
        },
      },
      required: ['query'],
      additionalProperties: false,
    },
  },
};

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function validateInventorySearchArgs(args) {
  if (!isPlainObject(args)) {
    throw new Error('Arguments must be an object');
  }

  for (const key of Object.keys(args)) {
    if (key !== 'query' && key !== 'limit') {
      throw new Error(`Unknown argument: ${key}`);
    }
  }

  const { query, limit } = args;

  if (typeof query !== 'string') {
    throw new Error('query must be a string');
  }

  if (limit !== undefined) {
    if (typeof limit !== 'number' || !Number.isInteger(limit)) {
      throw new Error('limit must be an integer');
    }
    if (limit < 1 || limit > 10) {
      throw new Error('limit must be between 1 and 10');
    }
  }

  return { query, limit };
}

export async function listTools() {
  return Object.values(TOOL_DEFINITIONS);
}

export async function callTool(name, args) {
  if (name !== 'inventory_search') {
    throw new Error(`Unknown tool: ${name}`);
  }

  const { query, limit } = validateInventorySearchArgs(args || {});

  const needle = query.toLowerCase();
  const matches = products.filter((product) =>
    typeof product?.name === 'string' && product.name.toLowerCase().includes(needle),
  );

  const effectiveLimit = limit ?? 10;
  const limited = matches.slice(0, effectiveLimit);

  if (limited.length === 0) {
    return {
      content: [
        {
          type: 'text',
          text: `No products matched "${query}".`,
        },
      ],
    };
  }

  const lines = limited.map((product) => `${product.id}: ${product.name}`);
  const header = `Found ${limited.length} product${limited.length === 1 ? '' : 's'} matching "${query}":`;
  const text = [header, ...lines].join('\n');

  return {
    content: [
      {
        type: 'text',
        text,
      },
    ],
  };
}

